    final byte[] keyBytes = new byte[32];
    final byte[] input = new byte[0];
    final byte[] ivBytes = new byte[16];
    final byte[] tag = new byte[16];
    final byte[] aad = new byte[r.nextInt() % 1000 + 1000];
    r.nextBytes(keyBytes);
    r.nextBytes(input);
    r.nextBytes(ivBytes);
    r.nextBytes(aad);
    {
